minor.proposed_text:
At the end of only_gains(), before the return, refuse insertions inside a published paragraph and gained lines that can hide text (tested in rule.py: the real change passes, and the splice and the comment are refused):
    BLOCK = re.compile(r"^(\s*$|#|\s*[-*+] |\s*\d+\. |\|)")
    HIDES = re.compile(r"<!--|-->|```|~~~|<details|^\s*\[[^\]]+\]:\s")
    for tag, i1, _, j1, j2 in ops:
        before, after = (a[i1-1] if i1 else ""), (a[i1] if i1 < len(a) else "")
        if not (before.strip() == "" or before.rstrip().endswith((".", ":", "|"))) or not BLOCK.match(after):
            raise SystemExit("gained lines inside a published paragraph: " + b[j1][:200])
        if any(HIDES.search(ln) for ln in b[j1:j2]):
            raise SystemExit("a gained line can hide published text: " + b[j1][:200])

f = git("fetch", "--quiet", "origin", "main")
if f.returncode != 0:
    raise SystemExit("git fetch origin main failed; cannot tell what origin/main holds: " + f.stderr.strip()[:200])

if info.sha != b["commit"]:
    raise SystemExit(f"{HUB} is at {info.sha[:8]}, the stage was built on {b['commit'][:8]}: if this stage was "
                     "already uploaded, run --verify (do not remove the stage); otherwise remove it and stage again")
